package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

// ここに sum(nums []int) int と maxOf(nums []int) int を書く
// （同じ package main なら、別ファイルに置いても import なしで呼べます）

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Scan()
	n, _ := strconv.Atoi(strings.Fields(sc.Text())[0])
	sc.Scan()
	fields := strings.Fields(sc.Text())
	nums := make([]int, n)
	for i := range n {
		nums[i], _ = strconv.Atoi(fields[i])
	}

	// ここから下を書く: 合計と最大値を出力する
	_ = nums
	_ = fmt.Println
}

